def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (after '+')
        if '+' in v:
            version_part, build = v.split('+', 1)
        else:
            version_part = v

        # Split pre-release (after '-')
        if '-' in version_part:
            core_part, prerelease = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # If both are None, they're equal (version without prerelease)
        if pre1 is None and pre2 is None:
            return 0
        # Version with prerelease sorts before version without
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare prerelease identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if identifiers are all-digit
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            # All-digit identifier sorts before non-digit
            if is_digit1 and not is_digit2:
                return -1
            if not is_digit1 and is_digit2:
                return 1

            # Compare numerically if both are all-digit
            if is_digit1 and is_digit2:
                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                if num1 > num2:
                    return 1
            else:
                # Compare as strings
                if id1 < id2:
                    return -1
                if id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        if len(pre1) > len(pre2):
            return 1

        return 0

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease = parse_version(version)
        # Return tuple: (major, minor, patch, prerelease_sort_key, original_index)
        # For prerelease, we need a key that sorts None (no prerelease) after prerelease
        if prerelease is None:
            prerelease_key = (1,)  # Sorts after prerelease (0,)
        else:
            # Convert prerelease identifiers to a sortable form
            prerelease_key = (0,) + tuple(
                (0, int(id)) if id.isdigit() else (1, id)
                for id in prerelease
            )
        return (major, minor, patch, prerelease_key, index)

    # Add original indices to maintain stable sort
    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

